// n8n/code/listExpansion.js — pure-JS HubSpot-list -> enrichment-events expansion.
//
// Phase 25 Plan 03 (INGEST-04, D-01/D-02/D-15). The plugin never holds a HubSpot token, so
// it hands the enrichment webhook a list identifier verbatim and n8n resolves it with the
// credential it already owns. This module is the pure half of that resolution: given the
// caller's body plus the two HubSpot responses, it returns either the SAME envelope shape
// `Parse HubSpot Event` already accepts, or a refusal carrying a plain-language reason.
// Pure, deterministic, no n8n globals — mirrors providerSelection.js, inlined into the
// Code node by the builder's inline() (Code nodes cannot require() siblings).
//
// expandListToEvents({ body, listResult, membershipsResult, maxRecords })
//   -> { events: [...], providers?: any, refused: false, reason: null }
//   -> { events: [],    refused: true,  reason: "<operator-facing sentence>" }
//
// IT REFUSES RATHER THAN TRUNCATING. Five ways a resolution can fail to produce a whole,
// enrichable record set, each with its own sentence and all of them with `events: []`:
//
//   1. A saved VIEW was named. HubSpot exposes no API for views, so a view is never
//      resolved against the LIST endpoint — a view name colliding with an unrelated list
//      name would enrich the wrong record set with NO error (25-RESEARCH.md Pitfall 2).
//      This is the recorded `refuse-and-redirect` decision (25-BLOCKERS.md, amendment #7).
//   2. The list name did not resolve (404, a 401/403 error item, or a body with no listId).
//   3. The membership body was unreadable, or the list has zero members. A zero-event
//      "success" is not a success: it would emit zero items into a `responseNode` webhook,
//      which returns NO response at all and hangs until Cloudflare 524s (D-22).
//   4. The membership page carried MORE ids than the ceiling.
//   5. The membership response carried a PAGING CURSOR — checked BEFORE the count and
//      refused even when the returned page is at or below the ceiling. This is the
//      cursor-follow requirement, discharged by refusal rather than by pagination: a
//      cursor means the read is a PAGE, not the list, and the single most repeated
//      failure in this milestone is a partial result impersonating a whole one (D-08,
//      D-20, D-22, D-23, D-33). Enumerating the remaining pages could not change the
//      outcome — the memberships endpoint pages at or below 102 members (live-probed
//      2026-07-31, 25-BLOCKERS.md) while the ceiling is derived from a ~100s response
//      window at ~36s/record, so a cursor ALWAYS implies "far more than the ceiling".
//      Following it would spend N requests to reach a refusal one request already proves.
//      ponytail: refuse-on-cursor, not paginate. Revisit only if the ceiling ever exceeds
//      a HubSpot membership page — it cannot while the response window bounds it.
//
// The provider selection is carried through UNCHANGED, including an explicitly empty
// selection: a list batch must burn exactly the providers the operator approved, no more
// (T-25-02). The key is copied only when the caller sent it, so an absent selection stays
// absent and `resolveEnabledProviders` resolves it to zero providers, fail-closed.
//
// Only record IDs cross this boundary. No HubSpot property value is read or emitted here
// (T-25-06).

// The exact operator-facing sentence recorded in 25-BLOCKERS.md as amendment #7, minus the
// document's markdown emphasis markers (this is an API refusal string, not a document).
// 25-04 uses the same words client-side.
const VIEW_REFUSAL =
  "I can't resolve a HubSpot view — HubSpot doesn't expose views through its API. " +
  "Save that view as a list in HubSpot and give me the list name, or paste the record IDs directly.";

// Accepts every spelling `Parse HubSpot Event`'s own normalizeObjectType() accepts, so a
// list envelope and a record-ID envelope agree on what an object type is.
const OBJECT_TYPE_IDS = {
  contact: "0-1", contacts: "0-1", "0-1": "0-1",
  company: "0-2", companies: "0-2", "0-2": "0-2",
};
const OBJECT_TYPE_BY_ID = { "0-1": "contacts", "0-2": "companies" };

function isPlainObject(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function isNumber(value) {
  return typeof value === "number" && isFinite(value);
}

function normalizeObjectType(raw) {
  const key = String(raw == null ? "" : raw).toLowerCase().trim();
  return OBJECT_TYPE_BY_ID[OBJECT_TYPE_IDS[key]] || null;
}

function objectTypeId(raw) {
  const key = String(raw == null ? "" : raw).toLowerCase().trim();
  return OBJECT_TYPE_IDS[key] || null;
}

function refuse(reason) {
  return { events: [], refused: true, reason };
}

// The list-by-name 200 body nests the list under `list`; tolerate a flat body and any
// shape mismatch (an onError item, an error body, a 404) by returning null.
function extractListId(listResult) {
  if (!isPlainObject(listResult)) return null;
  const source = isPlainObject(listResult.list) ? listResult.list : listResult;
  const listId = source.listId;
  if (listId === undefined || listId === null || listId === "") return null;
  return String(listId);
}

function hasPagingCursor(membershipsResult) {
  const paging = isPlainObject(membershipsResult) ? membershipsResult.paging : null;
  const next = isPlainObject(paging) ? paging.next : null;
  return !!(isPlainObject(next) && next.after);
}

// Fail closed: one unusable row refuses the whole read rather than emitting a null
// objectId that would enrich nothing while reporting a record count.
function memberIds(results) {
  const ids = [];
  for (const row of results) {
    const raw = isPlainObject(row)
      ? (row.recordId !== undefined ? row.recordId : row.id)
      : row;
    if (raw === undefined || raw === null || raw === "") return null;
    ids.push(String(raw));
  }
  return ids;
}

function oversizeRefusal(name, maxRecords, detail) {
  return (
    `The list "${name}" is larger than this backend can enrich in one request — the ` +
    `limit is ${maxRecords} record(s) per request, measured against the ~100s webhook ` +
    `response ceiling. ${detail} Nothing was enriched. Send record IDs instead, in ` +
    `batches of ${maxRecords} or fewer.`
  );
}

function expandListToEvents(input) {
  const opts = isPlainObject(input) ? input : {};
  const body = isPlainObject(opts.body) ? opts.body : null;
  const maxRecords = isNumber(opts.maxRecords) ? opts.maxRecords : 0;

  if (!body) {
    return refuse("The enrichment request carried no readable body, so there was nothing to resolve.");
  }

  // Checked FIRST and never resolved against the list endpoint (Pitfall 2).
  if (body.view !== undefined && body.view !== null) {
    return refuse(VIEW_REFUSAL);
  }

  const spec = isPlainObject(body.list) ? body.list : null;
  const name = spec && typeof spec.name === "string" ? spec.name.trim() : "";
  if (!name) {
    return refuse(
      "The enrichment request named no list, so there was nothing to resolve. Give me a " +
      "HubSpot list name, or paste the record IDs directly."
    );
  }

  const objectType = normalizeObjectType(spec.objectType);
  if (!objectType) {
    return refuse(
      `I can't tell whether "${name}" is a contact list or a company list. Name the object ` +
      `type as "contacts" or "companies" and I'll resolve it.`
    );
  }

  if (!extractListId(opts.listResult)) {
    return refuse(
      `HubSpot has no ${objectType} list named "${name}", or it refused to read it. Nothing ` +
      `was enriched. Check the list name in HubSpot, or paste the record IDs directly.`
    );
  }

  const memberships = opts.membershipsResult;
  const results = isPlainObject(memberships) && Array.isArray(memberships.results)
    ? memberships.results
    : null;
  if (!results) {
    return refuse(
      `HubSpot returned no readable membership list for "${name}". Nothing was enriched.`
    );
  }
  if (results.length === 0) {
    return refuse(
      `The ${objectType} list "${name}" has no members, so there is nothing to enrich.`
    );
  }

  // Cursor before count: with a cursor the returned length is a lower bound, and reporting
  // it as the size would understate the list.
  if (hasPagingCursor(memberships)) {
    return refuse(oversizeRefusal(
      name, maxRecords,
      "HubSpot returned only the first page of its members, so the full list is larger than " +
      "one response and its true size is unknown from here."
    ));
  }

  const total = isPlainObject(memberships) ? memberships.total : undefined;
  if (results.length > maxRecords || (isNumber(total) && total > maxRecords)) {
    const size = isNumber(total) && total > results.length ? total : results.length;
    return refuse(oversizeRefusal(name, maxRecords, `It has ${size} member(s).`));
  }

  const ids = memberIds(results);
  if (!ids) {
    return refuse(
      `HubSpot returned a membership row for "${name}" with no usable record id. Nothing was ` +
      `enriched.`
    );
  }

  const out = {
    events: ids.map((objectId) => ({ objectId: objectId, objectType: objectType })),
    refused: false,
    reason: null,
  };
  // Carried through unchanged, and ONLY when the caller sent it (T-25-02).
  if (Object.prototype.hasOwnProperty.call(body, "providers")) {
    out.providers = body.providers;
  }
  return out;
}

// --- n8n wrapper: Expand List To Events (Phase 25 Plan 03) ---
function nodeFirstJson(name) {
  try { const row = $(name).first(); return (row && row.json) || null; } catch (e) { return null; }
}
const MAX_LIST_RECORDS = 2;
const trigger = nodeFirstJson("Webhook Trigger") || {};
const result = expandListToEvents({
  body: trigger.body || trigger,
  listResult: nodeFirstJson("HubSpot List By Name"),
  membershipsResult: nodeFirstJson("HubSpot List Memberships"),
  maxRecords: MAX_LIST_RECORDS,
});
if (result.refused) {
  // Terminating item, NOT an exception: it carries the reason to the caller as a response.
  // `events: []` is what `IF List Expanded` gates on, so a refusal can never be enriched.
  return [{ json: { outcome: "refused", reason: result.reason, events: [] } }];
}
const envelope = { events: result.events };
if (result.providers !== undefined) envelope.providers = result.providers;
return [{ json: envelope }];

// n8n/code/providerSelection.js — pure-JS provider-selection cost gate for n8n Code nodes.
//
// Phase 16.1: the caller-supplied `providers` webhook field is the PRIMARY burn gate
// (CONTEXT Locked Decision 1 — no global build-time kill-switch). This module is pure,
// deterministic, and carries NO n8n globals — mirrors enrichmentGate.js exactly, inlined
// into Code nodes via the builder's inline() (Code nodes cannot require() siblings).
//
// parseWebhookBody(body)
//   -> { events, providers, mode }
//   Explicit payload contract (reviews A4): a bare HubSpot event array carries no
//   top-level `providers` slot; an envelope `{ providers, events: [...] }` object carries
//   the caller's selection at the envelope level. A single bare event object (neither an
//   array nor an envelope with `.events`) is treated as the one event, and its own
//   `.providers` field (if any) IS the envelope-level providers value here — the n8n
//   wrapper additionally falls back to `event.providers` per-event when this returns
//   undefined (`parsed.providers ?? event.providers`), covering the same single-event case
//   without double logic.
//   `mode` (Phase 36-03, 36-CONTEXT.md sec6): read at the envelope level with the IDENTICAL
//   idiom as `providers` — absent means today's behaviour byte-identically, `"write"` means
//   today's behaviour explicitly, and any other value is return-only (a typo can never
//   write). Two states, never an allow-list: `mode != null && String(mode).toLowerCase()
//   !== "write"`. That predicate is applied downstream at Decide Action, not here.
//
// resolveEnabledProviders(raw, allNames)
//   -> { provider_enabled: { <name>: boolean, ... }, providers_requested: [...] }
//   "all"                    -> every name in allNames enabled
//   "none" / "" / null / undefined / anything else (absent/unrecognized) -> none enabled
//   an array                 -> exactly those names (lowercased, intersected with
//                                allNames; unknown names dropped)
//
// extractCredits(provider, raw)
//   -> number | null
//   Three null-safe per-provider credit extractors (RESEARCH.md Task 1, live-curl-
//   validated). Forward-provisioned here for Plan 02 (16.1 does not call this at
//   runtime); unit-tested now so Plan 02 can consume it with zero further verification.
//   Every extractor returns null on ANY shape mismatch — never throws, never fails the run.

function parseWebhookBody(body) {
  const events = Array.isArray(body)
    ? body
    : (body && Array.isArray(body.events) ? body.events : [body]);
  const providers = (body && !Array.isArray(body)) ? body.providers : undefined;
  const mode = (body && !Array.isArray(body)) ? body.mode : undefined;
  return { events, providers, mode };
}

function resolveEnabledProviders(raw, allNames) {
  const all = Array.isArray(allNames) ? allNames : [];
  const allLower = all.map((n) => String(n).toLowerCase());
  let enabledLower;

  if (raw === "all") {
    enabledLower = allLower.slice();
  } else if (Array.isArray(raw)) {
    const requestedLower = raw.map((n) => String(n).toLowerCase());
    enabledLower = allLower.filter((n) => requestedLower.indexOf(n) !== -1);
  } else {
    // "none" | "" | null | undefined | any other unrecognized value -> nothing enabled
    // (CONTEXT Locked Decision 2 — safe default, explicit opt-in required).
    enabledLower = [];
  }

  const enabledSet = new Set(enabledLower);
  const provider_enabled = {};
  const providers_requested = [];
  for (const name of all) {
    const lower = String(name).toLowerCase();
    const isEnabled = enabledSet.has(lower);
    provider_enabled[name] = isEnabled;
    if (isEnabled) providers_requested.push(name);
  }

  return { provider_enabled, providers_requested };
}

function extractCredits(provider, raw) {
  const p = String(provider || "").toLowerCase();

  if (p === "lusha") {
    // 200 body -> { credits: { total, used, remaining } } [VERIFIED: live curl 200]
    return (raw && raw.credits && typeof raw.credits.remaining === "number")
      ? raw.credits.remaining : null;
  }

  if (p === "apollo") {
    // THIS account's key 403s (non-master) [VERIFIED: live curl 403] -> raw carries no
    // `remaining` field -> null. A master key's usage_stats body (undocumented shape for
    // this account) is read defensively: only a top-level numeric `remaining` is trusted.
    return (raw && typeof raw.remaining === "number") ? raw.remaining : null;
  }

  if (p === "zoominfo") {
    // JSON:API: data[0].attributes.usage[] keyed by limitType. [VERIFIED: live curl 200]
    // The real redeemable-records balance lives under limitType === "uniqueIdLimit";
    // fall back to the first entry with a non-zero totalLimit before giving up (Open
    // Question #1 — a different ZoomInfo plan may report its balance under another key).
    const usage = (raw && raw.data && raw.data[0] && raw.data[0].attributes
      && raw.data[0].attributes.usage) || [];
    if (!Array.isArray(usage)) return null;
    let entry = usage.find((u) => u && u.limitType === "uniqueIdLimit");
    if (!entry) entry = usage.find((u) => u && typeof u.totalLimit === "number" && u.totalLimit > 0);
    return (entry && typeof entry.usageRemaining === "number") ? entry.usageRemaining : null;
  }

  return null;
}

// n8n/code/matchProposal.js — pure-JS match-lane routing and proposal shaping.
//
// Phase 36 Plan 01 (36-CONTEXT.md §7 step 1). `Build Identity` stamps a single `lane`
// value per enrichment row so every downstream routing IF and adapter reads ONE source
// of truth instead of re-deriving its own predicate (36-CONTEXT.md
// <assumption_delta_decision>: "lane becomes the one field that names a row's
// identity-resolution strategy"). Pure, deterministic, no n8n globals — mirrors
// listExpansion.js/providerSelection.js, inlined into a Code node by the builder's
// inline() (Code nodes cannot import sibling modules at runtime).
//
// laneOf(row) -> "fetch_by_id" | "email" | "name" | "none"
//   The `fetch_by_id` branch mirrors `IF Bare Event`'s boolean expression exactly
//   (scripts/build_cloud_workflows.py, `IF Bare Event` node build):
//     !!$('Build Identity').item.json.object_id &&
//     !$('Build Identity').item.json.identity_keys.email
//   If the two predicates ever drift, a row is routed to one lane and filtered into
//   another and silently disappears (36-CONTEXT.md key_links).

function isPlainObject(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

// Trims a string field before the truthiness check so a whitespace-only value (e.g.
// companyName: "   ") is never mistaken for a present identity key. Non-strings pass
// through untouched — object_id may legitimately be a number.
function trimmedOrValue(value) {
  return typeof value === "string" ? value.trim() : value;
}

function laneOf(row) {
  const r = isPlainObject(row) ? row : {};
  const identityKeys = isPlainObject(r.identity_keys) ? r.identity_keys : {};
  const objectId = r.object_id;
  const email = trimmedOrValue(identityKeys.email);
  const lastName = trimmedOrValue(identityKeys.lastName);
  const companyName = trimmedOrValue(identityKeys.companyName);

  if (objectId && !email) return "fetch_by_id";
  if (email) return "email";
  if (lastName && companyName) return "name";
  return "none";
}

// tokenize(s) — lower-case, strip non-alphanumeric to spaces, split, drop empties.
// Used ONLY for the company token-overlap re-check below — never for substring
// matching (36-CONTEXT.md §12 Risk 3: a false NEGATIVE here costs one enrichment; a
// false POSITIVE corrupts a record, so this stays strict).
function tokenize(s) {
  return String(s == null ? "" : s)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .split(" ")
    .filter(Boolean);
}

function sharesToken(a, b) {
  const setA = new Set(tokenize(a));
  for (const tok of tokenize(b)) if (setA.has(tok)) return true;
  return false;
}

// mediumCandidates(searchResults, identityKeys) — re-verifies every HubSpot search hit
// BY VALUE before reporting it as a candidate. `CONTAINS_TOKEN` is fuzzy by design; a
// hit surviving the server-side filter is not yet a verified match (the BUG 22b lesson,
// applied prophylactically here — never trust that the search already filtered).
function mediumCandidates(searchResults, identityKeys) {
  const idKeys = isPlainObject(identityKeys) ? identityKeys : {};
  const lastName = trimmedOrValue(idKeys.lastName);
  const companyName = trimmedOrValue(idKeys.companyName);
  if (!lastName || !companyName || !Array.isArray(searchResults)) return [];

  const wantLastName = String(lastName).toLowerCase();
  const out = [];
  for (const hit of searchResults) {
    if (!isPlainObject(hit) || !isPlainObject(hit.properties)) continue;
    const props = hit.properties;
    const hitLastName = props.lastname == null ? "" : String(props.lastname).toLowerCase();
    if (hitLastName !== wantLastName) continue;
    if (!sharesToken(props.company, companyName)) continue;
    out.push({
      hs_object_id: hit.id,
      firstname: props.firstname != null ? props.firstname : null,
      lastname: props.lastname != null ? props.lastname : null,
      email: props.email != null ? props.email : null,
      jobtitle: props.jobtitle != null ? props.jobtitle : null,
      company: props.company != null ? props.company : null,
    });
  }
  return out;
}

// summarizeMatch({ lane, existingRecord, lookupFailed, candidates, objectIdSupplied })
//   -> { tier: "high"|"medium"|"none"|"unknown", auto, reason, candidates }
// `unknown` is not `none` (36-CONTEXT.md §6): "we did not find one" (none) and "we could
// not look" (unknown — the search failed or never ran) must stay distinguishable.
function summarizeMatch(input) {
  const opts = isPlainObject(input) ? input : {};
  const lane = opts.lane;
  const candidates = Array.isArray(opts.candidates) ? opts.candidates : [];

  if (opts.lookupFailed === true) {
    return { tier: "unknown", auto: false, reason: "the match search failed to run", candidates: [] };
  }

  if (lane === "fetch_by_id" || lane === "email") {
    const hasRecord = isPlainObject(opts.existingRecord) && Object.keys(opts.existingRecord).length > 0;
    if (hasRecord) {
      return { tier: "high", auto: true, reason: `matched by ${lane}`, candidates: [] };
    }
    return { tier: "none", auto: false, reason: "searched, no hit", candidates: [] };
  }

  if (lane === "name") {
    if (candidates.length > 0) {
      return { tier: "medium", auto: false, reason: "candidate(s) found by name+company, unverified", candidates };
    }
    return { tier: "none", auto: false, reason: "searched, no hit", candidates: [] };
  }

  // lane "none" (or anything unrecognized): there was no searchable identity, so the
  // search never ran — this is a "could not look", not a "did not find one".
  return { tier: "unknown", auto: false, reason: "no searchable identity — the row has no email, object id, or name+company pair", candidates: [] };
}

// isReturnOnly(mode) — the propose-mode write-guard predicate (36-CONTEXT.md §6/§4
// decision 1). Deliberately NOT an allow-list of mode names: two states, no third.
// `mode` absent/null or the write literal (case- and whitespace-insensitive) is `false`
// (today's write behaviour, byte-identical); every other value — including a typo — is
// `true` (return-only). That asymmetry is the fail-safe: an unrecognised value can only
// ever fail TOWARD returning proposals, never toward writing. String() never throws, so
// this never throws for any input.
function isReturnOnly(mode) {
  if (mode === undefined || mode === null) return false;
  return String(mode).trim().toLowerCase() !== "write";
}

// --- n8n wrapper: normalize event array + resolve providers (reviews A4) ---
function normalizeObjectType(input) {
  const v = String(input || "").toLowerCase();
  if (["contact", "contacts", "0-1"].includes(v)) return "contacts";
  if (["company", "companies", "0-2"].includes(v)) return "companies";
  return "unknown";
}
const PROVIDER_NAMES = ["lusha", "apollo", "zoominfo"];
const body = $json.body ?? $json;
const parsed = parseWebhookBody(body);
// Phase 36-03 Task 3 (36-CONTEXT.md sec7 step 6, D-15/D-22): refuse an oversize or empty
// events array WHOLE, never truncate, never hang. In-node here rather than a separate
// node (unlike Expand List To Events, whose separate-node placement guards against a
// MISSING events array being masked by parseWebhookBody's bare-event fallback): an
// oversized or empty array still IS an array, so that fallback never masks either case,
// and a separate node buys nothing extra. Mirrors ENRICH_EXPAND_LIST_TO_EVENTS's
// refusal-as-terminating-item shape: a single item carrying outcome:"refused" and a
// reason, never a thrown exception (a throw risks the Cloudflare 524, D-22) and never a
// partial map (D-15 — refuse whole, never truncate). object_type:"unknown" routes the
// refusal through the existing "IF Object Type Supported" false edge to "Unsupported
// Object Type" -> "Build Response", so the reason reaches the caller as a 200 with zero
// new nodes or edges.
// Phase 36-06 (37-CONTEXT.md §13 ceiling ruling): parsed.mode is read at the ENVELOPE
// level only (parseWebhookBody's contract) — an envelope that carries no top-level mode
// but whose individual events each carry one falls through to the write ceiling. That is
// fail-closed and correct: the row-level `parsed.mode ?? event.mode` fallback used below
// (and at Decide Action) is about which mode a ROW runs in; this is about how long the
// WHOLE request may take, and the stricter bound is the safe answer when the envelope
// itself has not declared its mode.
const MAX_WRITE_EVENTS = 2;
const MAX_PROPOSE_EVENTS = 20;
const MAX_EVENTS = isReturnOnly(parsed.mode) ? MAX_PROPOSE_EVENTS : MAX_WRITE_EVENTS;
if (parsed.events.length > MAX_EVENTS) {
  return [{ json: {
    outcome: "refused",
    reason: `Request carries ${parsed.events.length} events, more than this backend can ` +
      `enrich in one request — the limit is ${MAX_EVENTS} record(s) per request. ` +
      `Nothing was enriched. Send fewer records per request, in batches of ${MAX_EVENTS} ` +
      `or fewer.`,
    events: [],
    object_type: "unknown",
  } }];
}
if (parsed.events.length === 0) {
  return [{ json: {
    outcome: "refused",
    reason: "Request carries an empty events array — nothing to enrich. Send at " +
      "least one event.",
    events: [],
    object_type: "unknown",
  } }];
}
return parsed.events.map((event) => {
  const providersRaw = parsed.providers ?? event.providers;
  const { provider_enabled, providers_requested } = resolveEnabledProviders(providersRaw, PROVIDER_NAMES);
  const object_type = normalizeObjectType(event.objectType || event.objectTypeId);
  return { json: {
    event_id: `${event.subscriptionId || "sub"}:${event.objectId}:${event.eventId || event.occurredAt}`,
    object_id: event.objectId != null ? String(event.objectId) : null,
    object_type,
    property_name: event.propertyName || null,
    event_type: event.subscriptionType || event.eventType || null,
    occurred_at: event.occurredAt || new Date().toISOString(),
    provider_enabled,
    providers_requested,
    // Phase 36-03 (36-CONTEXT.md sec6): mode read at the envelope level exactly like
    // providers above, with the same per-event fallback. The two-state write-guard
    // predicate is applied downstream at Decide Action, not here — this only threads the
    // value onto the row so it rides the `...event` spread below to every later hop.
    mode: parsed.mode ?? event.mode ?? null,
    // MINIMUM-scope shim (Task 6, documented per the plan's own budget carve-out):
    // Build Identity/Build Company Identity still read direct body fields (email/
    // domain/...) rather than fetching the record fresh by object_id — restructuring
    // them to fetch-by-id is a larger port than this task's budget. Spreading the raw
    // event here keeps that shim working for a direct-field test payload; a genuine
    // HubSpot event carries none of these fields, so on the real path Build Identity
