  }
  const res = item.json || {};
  let existingRecord = {};
  if (Array.isArray(res.results)) {                                     // search list
    if (res.results.length) {
      const first = res.results[0];
      existingRecord = { ...(first.properties || {}), hs_object_id: first.id };
    }
