}
const ALLOW_HUBSPOT_RECORD_WRITES = "false";
const ALLOW_HUBSPOT_CREATE = "false";
const ALLOW_HUBSPOT_REVIEW_WRITES = "false";
const TEST_RECORD_DOMAINS = "";
const TEST_RECORD_IDS = "";
const ALLOW_SJ3_DRAIN_WRITES = "true";
function _writeSafetyAllows(action, hsObjectId, domain) {
  // Review writeback has its OWN authority (D-02): the review action never consults
  // ALLOW_HUBSPOT_RECORD_WRITES, and no other action consults ALLOW_HUBSPOT_REVIEW_WRITES,
  // so arming either gate grants nothing on the other path. The allowlist below is
  // shared and mandatory for both.
  if (action === "review") {
    if (String(ALLOW_HUBSPOT_REVIEW_WRITES).toLowerCase() !== "true") return false;
  } else {
    if (String(ALLOW_HUBSPOT_RECORD_WRITES).toLowerCase() !== "true") return false;
    if (action === "create" && String(ALLOW_HUBSPOT_CREATE).toLowerCase() !== "true") return false;
  }
  const allowedDomains = String(TEST_RECORD_DOMAINS).split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
  const allowedIds = String(TEST_RECORD_IDS).split(",").map((s) => s.trim()).filter(Boolean);
  if (!allowedDomains.length && !allowedIds.length) return false;  // empty allowlist denies everything
  if (hsObjectId && allowedIds.indexOf(String(hsObjectId)) !== -1) return true;
  if (domain && allowedDomains.indexOf(String(domain).toLowerCase()) !== -1) return true;
  return false;
}

return $input.all().map((it) => {
  const row = it.json;
  // Phase 36-04 Task 1 (36-CONTEXT.md §4 decision 1/§6): computed once per row from the
  // shared two-state predicate — never a third mode name, never an ALLOW_* constant.
  const returnOnly = isReturnOnly(row.mode);
  const properties = { ..._buildContactPatch(row.merge), ...(row.lusha_ids || {}) };
  const hs_object_id = (row.existingRecord && row.existingRecord.hs_object_id) || null;
  const id = row.identity_keys || {};
  const domain = id.domain;
  if (row.action === "create" && id.email && !returnOnly) {
    // BUG 19: canonicalPatch never carries email (manual_protected — an UPDATE rule), so
    // an unseeded create writes a contact the by-email search can never find, and every
    // later run creates another. Keyed on row.action (pre-gate): a write_blocked create
    // sends nothing, and an enrich must never receive this seed (that IS the clobber the
    // policy exists to prevent). Also gated on !returnOnly (36-CONTEXT.md §6): a propose
    // response's `properties` carries only what the waterfall discovered — the caller's
    // own identity must never be echoed back as if it were a finding.
    properties.email = id.email;
  }
  let action = row.action;
  if (returnOnly) {
    // Phase 36-04 Task 1 (36-CONTEXT.md §4 decision 1): set BEFORE _writeSafetyAllows,
    // unconditionally on the mode predicate alone — no ALLOW_* constant is read on this
    // branch. That ordering IS the safety property: propose mode's no-write guarantee
    // cannot be re-armed by flipping a write-safety flag. "proposed" matches neither
    // "IF Create" (=="create") nor "IF Enrich" (=="enrich"), so the row exits via
    // "IF Enrich"'s existing false lane into "Build Response" — no new edge needed.
    action = "proposed";
  } else if (action === "create" && row.match && row.match.tier === "medium") {
    // A MEDIUM match is a proposal the caller has not judged — `auto` is false by
    // contract (matchProposal.js summarizeMatch). Auto-creating against it would
    // duplicate the very candidate mediumCandidates() just surfaced. Like "proposed",
    // "needs_match_review" matches neither IF Create nor IF Enrich and exits via
    // IF Enrich's false lane.
    action = "needs_match_review";
  }
  if ((action === "create" || action === "enrich") &&
      !_writeSafetyAllows(action, hs_object_id, domain)) {
    action = "write_blocked";
  }
  // BUG 27 (live 400 on execution 328): HubSpot v3 PATCH rejects JSON arrays —
  // multi-checkbox values must be semicolon-joined strings. Single choke point.
  // D-07 (43-01, PIPE-01, row 5, defensive parity with the companies branch): a second
  // branch coerces any boolean-typed value to its quoted string form — no boolean-typed
  // ICP candidate is a live contacts field today (DEFAULT_CONTACT_POLICY is string-only),
  // but this closes the class here too rather than leaving one branch un-guarded.
  for (const k of Object.keys(properties)) {
    if (Array.isArray(properties[k])) properties[k] = properties[k].join(";");
    else if (typeof properties[k] === "boolean") properties[k] = properties[k] ? "true" : "false";
  }
  return { json: {
    action,
    object_type: row.object_type || "contacts",
    hs_object_id,
    gap_flag: row.gap_flag === true,
    row_id: row.row_id ?? null,
    mode: row.mode ?? null,
    match: row.match ?? summarizeMatch({ lane: row.lane }),
    properties
  }};
});

// Build Company Identity — companies branch.
// Domain is the identity anchor for companies (email is for contacts). Lowercased +
// stripped of scheme/www so it matches HubSpot's stored `domain` form.
function cleanDomain(raw) {
  if (!raw) return null;
  let d = String(raw).trim().toLowerCase();
  d = d.replace(/^https?:\/\//, "").replace(/^www\./, "").split("/")[0];
  return d || null;
}
return $input.all().map((it) => {
  const row = it.json;
  const domain = cleanDomain(row.domain || row.website);
  return { json: { ...row,
    object_type: "companies",
    identity_keys: { domain, companyName: row.company || row.name || null },
  }};
});

// Adapt Company Search -> existingRecord — companies branch.
// Same contract as the contacts Adapt Search: per-row, same order, 0 results => {} => CREATE.
const rows = $('Build Company Identity').all();
const search = $('HubSpot Company Search').all();
return rows.map((it, i) => {
  const row = it.json;
  const item = search[i];
  const failed = !item || item.error || (item.json && item.json.error);
  if (failed) {
    return { json: { ...row, existingRecord: {}, lookup_failed: true } };
  }
  const res = item.json || {};
  let existingRecord = {};
  if (Array.isArray(res.results)) {
    if (res.results.length) {
      const first = res.results[0];
      existingRecord = { ...(first.properties || {}), hs_object_id: first.id };  // search envelope
    }
  } else if (res.properties) {
    existingRecord = { ...res.properties, hs_object_id: res.id };                // single object
  }
  return { json: { ...row, existingRecord, lookup_failed: false } };
});

// normalizeEmail.js — pure-JS email normalization for n8n Code nodes.
//
// normalizeEmailBasic does a BASIC syntactic check + trim/lowercase only. The
// authoritative validation is the external rapid-email-verifier API downstream;
// applyEmailVerification maps that verifier's response onto the row. This mirrors
// src/normalizer.py normalize_email closely enough for identity/dedupe parity:
// obviously-malformed -> null, otherwise trimmed+lowercased.

function normalizeEmailBasic(raw) {
  if (raw === null || raw === undefined) return null;
  const s = String(raw).trim().toLowerCase();
  if (s === "") return null;
  // Basic shape: local@domain.tld, no spaces, one @, a dotted domain.
  // Deliberately conservative — the verifier API is the real authority.
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)) return null;
  return s;
}

// Map a rapid-email-verifier result onto the row. `verifierResult` shape:
//   { status: "VALID"|"PROBABLY_VALID"|"INVALID_FORMAT"|"INVALID_DOMAIN"|"DISPOSABLE",
//     aliasOf?: "canonical@example.com" }
// Returns the fields to merge onto the row.
function applyEmailVerification(row, verifierResult) {
  const status = (verifierResult && verifierResult.status) || "INVALID_FORMAT";
  const alias = verifierResult && verifierResult.aliasOf;
  const raw = row ? row.email : undefined;

  // aliasOf is the canonical address when the verifier resolved one.
  const canonical = alias
    ? normalizeEmailBasic(alias)
    : normalizeEmailBasic(raw);

  const valid = status === "VALID" || status === "PROBABLY_VALID";

  return {
    email_normalized: valid ? canonical : normalizeEmailBasic(raw),
    email_valid: valid,
    email_status: status,
    needs_review_reason: valid ? null : `email verifier: ${status}`,
  };
}

// normalizePhone.js — pure-JS AU phone normalizer for n8n Code nodes.
//
// DISCLAIMER: This is an AU-ONLY heuristic, NOT libphonenumber. It cannot import
// npm (n8n Code nodes run pure JS with no requires), so it recognises only the AU
// formats the ingestion pipeline actually sees. Any number that is non-AU or
// ambiguous returns null — the caller must route null to review, never silently
// drop or guess. A leading '+' is trusted as already-E.164 and passed through
// (separators stripped) WITHOUT a validity check, so an invalid '+...' string is
// kept as-is here where the Python oracle (phonenumbers.is_valid_number) would
// reject it. Swap this for a phone-validation API for global fidelity later.
//
// Mirrors src/normalizer.py normalize_phone for the AU cases the parity test pins.

function normalizePhoneAU(raw) {
  if (raw === null || raw === undefined || raw === "") return null;
  // Strip spaces, dashes, parens, dots — everything that is pure separator.
  const s = String(raw).replace(/[\s\-().]/g, "");
  if (s === "") return null;

  // Already international: trust the '+', keep the digits after it.
  if (s.startsWith("+")) {
    const digits = s.slice(1);
    if (!/^\d+$/.test(digits)) return null; // "+garbage" -> review
    return "+" + digits;
  }

  if (!/^\d+$/.test(s)) return null; // any non-digit leftover -> not AU/ambiguous

  // 0XXXXXXXXX — 10-digit AU national (mobile 04.. or landline 0[2378]..).
  if (s.length === 10 && s[0] === "0") {
    return "+61" + s.slice(1);
  }

  // 61XXXXXXXXX — AU country code without the '+'.
  if (s.length === 11 && s.startsWith("61")) {
    return "+" + s;
  }

  return null; // anything else is non-AU or ambiguous -> review
}

// normalizePhone(raw, region) — region-aware E.164 normalizer.
//
// Still NOT libphonenumber (n8n Code nodes can't require npm), but deterministic and
// keyed off the ISO2 country the PROVIDERS already return (Lusha location.country_iso2,
// Apollo person country, etc.) instead of guessing. Rules, in order:
//   1. Already `+E.164` -> trust and keep (digits 6-15).
//   2. Known region -> prepend that country's calling code (stripping a trunk 0 for
//      AU/NZ/GB/IE, a leading 1 for US/CA), gated by a per-country NSN-length sanity check.
//   3. Unknown/absent region -> fall back to normalizePhoneAU (AU heuristic). A non-AU
//      national number then returns null -> the caller drops it (never a bad write).
// The NSN-length gate is a sanity filter, not full validation; swap for a phone API when
// global precision matters (same external-call pattern as the email verifier).
const CALLING_CODE = { AU: "61", NZ: "64", US: "1", CA: "1", GB: "44", IE: "353", IN: "91", SG: "65" };
