//   - none of the above ....................... SKIP
//
// PURE + DETERMINISTIC: `nowIso` injected (no Date.now here). `opts.validity` is an
// optional { fieldName: boolean } map from an upstream verifier; when absent, email
// falls back to basic syntax and phone to normalizePhoneAU (E.164) checks.


function _isBlank(v) {
  return v === null || v === undefined || v === "" ||
         (Array.isArray(v) && v.length === 0);
}

function _isEmpty(record) {
  if (!record) return true;
  return Object.keys(record).every((k) => _isBlank(record[k]));
}

function _staleAfterDays(policy, field) {
  const p = policy && policy[field];
  return p && p.stale_after_days != null ? p.stale_after_days : null;
}

// Phase 15: staleness reads the REAL cache-key property, never the provenance blob
// (HubSpot cannot filter/read inside a JSON text property). Any leading `lv_` on `field`
// is stripped and re-prefixed exactly once, so `lv_org_type` -> `lv_org_type_verified_at`
// and `jobtitle` -> `lv_jobtitle_verified_at` (mirrors PN-4 composition).
function _cacheKeyName(field) {
  const base = String(field).replace(/^lv_/, "");
  return `lv_${base}_verified_at`;
}

function _fieldValid(field, value, validity) {
  if (validity && Object.prototype.hasOwnProperty.call(validity, field)) {
    return validity[field] === true;
  }
  if (field === "email") return normalizeEmailBasic(value) !== null;
  if (field === "phone" || field === "mobilephone") return normalizePhoneAU(value) !== null;
  return true; // no validation rule for this field
}

function decideAction(existingRecord, requiredFields, policy, nowIso, opts) {
  opts = opts || {};
  const validity = opts.validity || null;
  requiredFields = requiredFields || [];
  policy = policy || {};

  if (_isEmpty(existingRecord)) {
    return { action: "create", staleFields: [], missingFields: [], invalidFields: [],
             reason: "no existing record" };
  }

  const missingFields = [];
  const staleFields = [];
  const invalidFields = [];
  const now = Date.parse(nowIso);

  for (const field of requiredFields) {
    const value = existingRecord[field];

    if (_isBlank(value)) {
      missingFields.push(field);
      continue; // missing dominates — nothing else to check
    }

    if (!_fieldValid(field, value, validity)) {
      invalidFields.push(field);
    }

    const ttl = _staleAfterDays(policy, field);
    if (ttl != null) {
      const verifiedAt = existingRecord[_cacheKeyName(field)];
      if (_isBlank(verifiedAt)) {
        staleFields.push(field); // present value, unknown freshness -> validate
      } else {
        const then = Date.parse(verifiedAt);
        const ageDays = Number.isNaN(then) || Number.isNaN(now) ? Infinity : (now - then) / 86400000;
        if (ageDays > ttl) staleFields.push(field);
      }
    }
  }

  const needs = missingFields.length || staleFields.length || invalidFields.length;
  if (needs) {
    const parts = [];
    if (missingFields.length) parts.push(`missing: ${missingFields.join(",")}`);
    if (staleFields.length) parts.push(`stale: ${staleFields.join(",")}`);
    if (invalidFields.length) parts.push(`invalid: ${invalidFields.join(",")}`);
    return { action: "enrich", staleFields, missingFields, invalidFields, reason: parts.join("; ") };
  }

  return { action: "skip", staleFields: [], missingFields: [], invalidFields: [],
           reason: "all required fields present, fresh and valid" };
}

// --- n8n wrapper: decideAction(existingRecord) -> create | enrich | skip ---
const REQUIRED = ["lv_org_type", "lv_produces_content"];
const POLICY = {
  lv_org_type: { stale_after_days: 180 },
  lv_produces_content: { stale_after_days: 180 },
};
const NOW = new Date().toISOString();
// Phase 47.5 (RECOMP-01): the on-demand veto-recompute intent, read at REQUEST level by
// node name from the ROOT `Parse HubSpot Event` — never bare $json, and never `.item`.
// `.first()` makes this a WHOLE-REQUEST decision, which is what keeps the two lanes of
// `IF Company Recompute` mutually exclusive for a whole execution — the property every
// existing multi-inbound convergence in this graph relies on, and the reason none of them
// has ever mis-fired. Hoisted out of the per-row map for the same reason.
//
// The try/catch is the SAME idiom ENRICH_NORMALIZE_SCORE_CO's nodeAll() uses, and it is
// load-bearing, not decorative: this constant is shared by three workflows and only the
// enrichment webhook one HAS a `Parse HubSpot Event` node. n8n throws on $() for a node
// that does not exist in the current workflow, so `wf_enrichment_local_live`'s
// "Company Gate" and `wf_scheduled_maintenance_cloud`'s "SJ-2 Company Gate" would throw on
// every row without it. Failing to false is the fail-closed direction: those two workflows
// keep exactly the behaviour they have today.
let RECOMPUTE_REQUESTED = false;
try {
  const _first = $('Parse HubSpot Event').first();
  RECOMPUTE_REQUESTED = !!(_first && _first.json && _first.json.recompute === true);
} catch (e) { RECOMPUTE_REQUESTED = false; }
return $input.all().map((it) => {
  const row = it.json;
  const gate = decideAction(row.existingRecord || {}, REQUIRED, POLICY, NOW);
  let action = gate.action;
  // Fail-closed (Task 6, review #8) — see ENRICH_GATE's identical comment (contacts).
  if (row.lookup_failed === true && action === "create") action = "skip";
  // Phase 47.5 (RECOMP-01) — exactly two mappings, and only under the request-level intent
  // resolved above:
  //   skip   -> enrich            a COMPLETE record is otherwise frozen: Normalize + Score
  //                               drops it and the sole veto writer never runs (exec 11846)
  //   create -> recompute_refused a recompute for a record that resolved to nothing must
  //                               NEVER seed a junk company (BUG 19 shape). It falls
  //                               through both write IFs to Build Response.
  // `enrich` is untouched. `gate` itself is left intact apart from the refusal reason —
  // the reason string is what makes the outcome readable in the response.
  if (RECOMPUTE_REQUESTED) {
    if (action === "skip") {
      action = "enrich";
    } else if (action === "create") {
      action = "recompute_refused";
      gate.reason =
        "a recompute was requested for a company that did not resolve to an existing " +
        "record — refused rather than created (" + gate.reason + ")";
    }
  }
  return { json: { ...row, gate, action } };
});

// lushaRequest.js — v3 Lusha request-body builders (contacts + companies lanes) and the
// contacts-lane reveal allow-list.
//
// Phase 20 (Lusha v2 -> v3 migration). Shapes confirmed live against api.lusha.com on
// 2026-07-30 — see docs/LUSHA-V3-CONTRACT.md (the contract of record, not RESEARCH.md's
// pre-probe hypothesis).
//
// REQ-lusha-selective-reveal was re-scoped upstream (commit 559eda5) after the v3 probe
// REFUTED assumption A3 (selective reveal as a cost lever — a reveal:["emails"] call and a
// reveal:["emails","phones"] call against the same stored id billed the SAME 0 credits).
// reveal[] survives here as PII-MINIMIZATION HYGIENE ONLY: never ask the provider to
// reveal a field HubSpot already holds, even though doing so wouldn't cost more. The real
// cost lever is stored-id re-enrichment (Plan 04), not this module.
//
// docs/LUSHA-V3-CONTRACT.md §6 confirms an empty `reveal: []` is REJECTED (400: "reveal
// must contain at least 1 elements") — that constraint was measured against
// /v3/contacts/enrich, and is treated here as a general request-validation rule that also
// applies to /v3/contacts/search-and-enrich (the endpoint this module builds for — see
// §7's "ship on the combined endpoint" verdict). lushaContactBody() therefore always
// emits a non-empty reveal array, defaulting to ["emails"] when nothing is missing.
//
// NO npm, dependency-free (no CommonJS/ESM module-loading statements) — this module is
// inline()'d verbatim into n8n Code nodes by scripts/build_cloud_workflows.py (mirrors
// normalizeProviders.js's module convention).

// Fixed allow-list: HubSpot field name (as it appears in the enrichment gate's
// `missingFields` array) -> the Lusha v3 reveal value string. ONLY two entries.
//
// - `jobtitle` is deliberately absent: docs/LUSHA-V3-CONTRACT.md's contacts response
//   (§4) returns `jobTitle` in the free preview (no reveal gate covers it) — it is never
//   a billed/gated reveal field, so it must never appear in a reveal list.
// - landline `phone` is deliberately absent: it is not in the contacts gate's REQUIRED
//   list (scripts/build_cloud_workflows.py ENRICH_GATE: ["email","jobtitle","mobilephone"]),
//   so it can never legitimately appear in `missingFields` — omitting it here is a second,
//   independent line of defense (belt-and-braces, not load-bearing on its own).
const LUSHA_REVEAL_BY_FIELD = Object.freeze({
  email: "emails",
  mobilephone: "phones",
});

// lushaReveal(missingFields) -> reveal value array, filtered through the frozen literal
// map above. Threat T-20-02 mitigation: reads use `hasOwnProperty` so a prototype-chain
// property name (e.g. "__proto__", "constructor") can never resolve to a value, and
// anything not an exact literal key (e.g. the ungated landline "phone") silently drops
// out rather than reaching the provider request. Sorted so output order never depends on
// input order (keeps the contract test deterministic). Tolerates non-array input.
function lushaReveal(missingFields) {
  if (!Array.isArray(missingFields)) return [];
  const out = [];
  for (const field of missingFields) {
    if (typeof field !== "string") continue;
    if (Object.prototype.hasOwnProperty.call(LUSHA_REVEAL_BY_FIELD, field)) {
      out.push(LUSHA_REVEAL_BY_FIELD[field]);
    }
  }
  return out.sort();
}

function _blank(v) {
  return v === null || v === undefined || v === "";
}

// lushaContactBody(identityKeys, missingFields) -> the v3
// POST /v3/contacts/search-and-enrich request body.
//
// identityKeys accepts any subset of the confirmed contacts identity properties
// (docs/LUSHA-V3-CONTRACT.md §3): email, linkedin_url, firstName, lastName, companyName,
// domain. This is deliberately generic — the CLOUD emission site passes only
// {email, linkedin_url} (the identity set live-confirmed for it pre-migration), while the
// LOCAL-LIVE builder and the dry-run harness pass the broader
// {firstName,lastName,companyName,domain,email,linkedin_url} set they already send. That
// split is carried forward on purpose (see scripts/build_cloud_workflows.py's Lusha Enrich
// node comment), not unified by this module.
//
// When no usable identity key is present, this returns the no-identity skip-not-retry form
// (`{ contacts: [] }`) rather than an element whose only content is a caller-chosen id —
// v3 rejects the v2-style synthetic `contactId` index key outright (docs/LUSHA-V3-CONTRACT.md
// §3: "property contactId should not exist").
function lushaContactBody(identityKeys, missingFields) {
  const id = identityKeys || {};
  const contact = {};
  if (!_blank(id.email)) contact.email = id.email;
  if (!_blank(id.linkedin_url)) contact.linkedinUrl = id.linkedin_url;
  if (!_blank(id.firstName)) contact.firstName = id.firstName;
  if (!_blank(id.lastName)) contact.lastName = id.lastName;
  if (!_blank(id.companyName)) contact.companyName = id.companyName;
  if (!_blank(id.domain)) contact.companyDomain = id.domain;

  if (Object.keys(contact).length === 0) {
    return { contacts: [] };
  }

  const revealed = lushaReveal(missingFields);
  // §6: an empty reveal is an invalid request — default to the minimal non-empty set.
  const reveal = revealed.length ? revealed : ["emails"];

  return { contacts: [contact], reveal };
}

// lushaContactEnrichByIdBody(storedId, missingFields) -> the v3 POST /v3/contacts/enrich
// request body — the CONFIRMED-FREE stored-id re-enrichment path (Plan 20-04 Task 2b;
// docs/LUSHA-V3-CONTRACT.md §8/§8.1, 4/4 live calls billed 0 credits). A DELIBERATE
// SIBLING of lushaContactBody(), never folded into it: /contacts/enrich takes a
// top-level `ids` array and REJECTS the `contacts`/identity-object shape entirely
// (§8.1 live-confirmed: "property contacts should not exist"; a bare `{"id": ...}` is
// also rejected, "property id should not exist") — this is a genuinely different
// endpoint + body shape, not an extra property on the search-and-enrich body Plan 02
// built. Reuses the SAME lushaReveal() allow-list/default as lushaContactBody() — the
// stored id changes which identity the request resolves, not which fields are worth
// paying to reveal.
//
// Returns null when storedId is blank (null/undefined/""): the caller's contract is
// "null means build the normal lushaContactBody() request instead", so an absent stored
// id can never regress a first-time enrichment — this function is simply never called
// for that case, and lushaContactBody()'s output stays byte-identical to Plan 02's.
function lushaContactEnrichByIdBody(storedId, missingFields) {
  if (_blank(storedId)) return null;
  const revealed = lushaReveal(missingFields);
  const reveal = revealed.length ? revealed : ["emails"];
  return { ids: [storedId], reveal };
}

// lushaCompanyBody(identityKeys) -> the v3 POST /v3/companies/search-and-enrich request
// body. domain ONLY (docs/LUSHA-V3-CONTRACT.md §5) — BUG 17 established live that
// `companyName` 400s this lane ("property companyName should not exist" on the retired
// v2 endpoint), and the v3 probe's winning body (§5) confirms `domain` is still the only
// accepted identity property. No `reveal` key: §5/§6 confirm the companies lane exposes
// no `has`/`canReveal` structure at all — there is no reveal mechanism to derive one for.
function lushaCompanyBody(identityKeys) {
  const id = identityKeys || {};
  if (_blank(id.domain)) {
    return { companies: [] };
  }
  return { companies: [{ domain: id.domain }] };
}

// --- n8n wrapper: Build Company Provider Requests — companies branch. ---
// Lusha: POST /v3/companies/search-and-enrich, body {"companies":[{"domain":...}]}
// (docs/LUSHA-V3-CONTRACT.md §5, live-confirmed 2026-07-30) — built by the shared
// lushaCompanyBody(), domain ONLY. History: the retired v2 GET /v2/company?domain=
// endpoint (BUG 17, re-probed live 2026-07-29 against racingnsw.com.au) rejected
// `companyName` outright ("property companyName should not exist" as a query param,
// mirroring the same-shaped rejection the old POST body got for `domain`) — that is
// why companyName has never been part of the Lusha company identity and still isn't
// under v3; it lives on in identity_keys for the other providers only.
// Apollo: unchanged, still POST /v1/organizations/enrich?domain=.
return $input.all().map((it) => {
  const row = it.json;
  const id = row.identity_keys || {};
  const lusha_company_body = lushaCompanyBody(id);
  const apollo_org_url =
    "https://api.apollo.io/v1/organizations/enrich?domain=" + encodeURIComponent(id.domain || "");
  return { json: { ...row, lusha_company_body, apollo_org_url } };
});

// adaptFetchById.js — pure-JS adapter for the HubSpot fetch-by-objectId lane (Phase 16.4).
//
// adaptFetchByIdResult(item) maps ONE row of a HubSpot search-by-hs_object_id node's raw
// output into { existingRecord, lookup_failed, fetch_diagnostic }. Same three response
// shapes as ENRICH_ADAPT_SEARCH (search envelope / single object / bare object), but
// DIFFERENT 0-results semantics: unlike an email/domain search, the id here came from a
// real HubSpot webhook event, so zero results means deleted/merged/stale-event — not
// confirmed-absent — and hs_object_id is server-assigned so a create could never set it
// anyway. Both the error case and the 0-results case map to lookup_failed:true, reusing
// the EXISTING create->skip override at ENRICH_GATE/ENRICH_CO_GATE unmodified — zero new
// failure vocabulary. `fetch_diagnostic` carries enough to tell the two failure modes
// apart at a glance in n8n's per-node execution view (Track B: hs_object_id filterability
// is MEDIUM confidence, unproven against this portal).
//
// backfillIdentityKeys(objectType, existingRecord, currentIdentityKeys) fills ONLY the
// currently-blank identity_keys from the fetched record — never overwrites a value the
// caller/event already supplied (a caller-envelope payload that somehow reaches this lane
// keeps its own values). Field derivation mirrors ENRICH_BUILD_IDENTITY (contacts) /
// ENRICH_BUILD_CO_IDENTITY (companies) exactly, so the backfilled shape is identical to
// what the direct-field lane would have produced.

function _truncate(s, n) {
  const str = String(s === null || s === undefined ? "" : s);
  return str.length > n ? str.slice(0, n) : str;
}

function _isBlank(v) {
  return v === null || v === undefined || v === "";
}

function adaptFetchByIdResult(item) {
  const failed = !item || item.error || (item.json && item.json.error);
  if (failed) {
    const errText = (item && (item.error || (item.json && item.json.error))) || "no response item";
    return {
      existingRecord: {},
      lookup_failed: true,
      fetch_diagnostic: `error: ${_truncate(errText, 200)}`,
    };
  }

  const res = item.json || {};

  if (Array.isArray(res.results)) {                                       // search envelope
    if (!res.results.length) {
      // 0 results on a KNOWN hs_object_id: the event came from HubSpot itself, so this
      // means deleted/merged/stale-event, NOT confirmed-absent (unlike an email/domain
      // search's legitimate 0-results case). Fail closed via lookup_failed rather than
      // risk a duplicate create on a server-assigned id a create could never set anyway.
      return {
        existingRecord: {},
        lookup_failed: true,
        fetch_diagnostic: "zero-results: hs_object_id not found (deleted/merged/stale event)",
      };
    }
    const first = res.results[0];
    return {
      existingRecord: { ...(first.properties || {}), hs_object_id: first.id },
      lookup_failed: false,
      fetch_diagnostic: "ok: matched via search envelope",
    };
  }

  if (res.properties) {                                                   // single object
    return {
      existingRecord: { ...res.properties, hs_object_id: res.id },
      lookup_failed: false,
      fetch_diagnostic: "ok: matched via single object",
    };
  }

  if (res.id) {                                                           // bare object
    return { existingRecord: res, lookup_failed: false, fetch_diagnostic: "ok: matched via bare object" };
  }

  // Well-formed 200 but an unrecognized shape — fail closed, never guess confirmed-absent.
  return {
    existingRecord: {},
    lookup_failed: true,
    fetch_diagnostic: "error: unrecognized response shape",
  };
}

// Contacts: mirrors ENRICH_BUILD_IDENTITY's field derivation exactly.
const _CONTACT_MAP = {
  email: "email",
  firstName: "firstname",
  lastName: "lastname",
  companyName: "company",
  linkedin_url: "lv_linkedin_url",
};

// Companies: mirrors ENRICH_BUILD_CO_IDENTITY's field derivation. `domain` is cleaned
// below (not a raw pass-through) — see cleanDomain.
const _COMPANY_MAP = {
  domain: "domain",
  companyName: "name",
};

// Identical to ENRICH_BUILD_CO_IDENTITY's cleanDomain. HubSpot's own stored `domain`
// property is normally already in this form, but the fetched value is run through the
// SAME cleaning defensively (never a raw pass-through) so a backfilled domain is
// guaranteed to match the stored form the rest of the companies branch expects, even if
// the property ever carries a scheme/www/path variant.
function cleanDomain(raw) {
  if (!raw) return null;
  let d = String(raw).trim().toLowerCase();
  d = d.replace(/^https?:\/\//, "").replace(/^www\./, "").split("/")[0];
  return d || null;
}

function backfillIdentityKeys(objectType, existingRecord, currentIdentityKeys) {
  if (!existingRecord || Object.keys(existingRecord).length === 0) {
    return currentIdentityKeys; // nothing fetched -> nothing to backfill, unchanged
  }

  const out = { ...(currentIdentityKeys || {}) };
  const isCompany = objectType === "companies";
  const map = isCompany ? _COMPANY_MAP : _CONTACT_MAP;

  for (const keyName of Object.keys(map)) {
    if (!_isBlank(out[keyName])) continue; // never overwrite a caller-supplied value
    const recordField = map[keyName];
    let v = existingRecord[recordField];
    if (isCompany && keyName === "domain") v = cleanDomain(v);
    if (!_isBlank(v)) out[keyName] = v;
  }

  if (!isCompany && _isBlank(out.domain) && !_isBlank(out.email)) {
    // Contacts only: domain derives from the (possibly just-backfilled) email's own
    // domain part — mirrors ENRICH_BUILD_IDENTITY:806 exactly.
    const parts = String(out.email).split("@");
    if (parts.length === 2 && parts[1]) out.domain = parts[1];
  }

  return out;
}

// --- n8n wrapper: adapt "HubSpot Company Fetch By Id" -> existingRecord + backfilled identity_keys ---
// Same node-name-only recovery discipline as the contacts sibling — no bare current-item
// read.
const rows = $('Build Company Identity').all();
const fetched = $('HubSpot Company Fetch By Id').all();
return rows.map((it, i) => {
  const row = it.json;
  const { existingRecord, lookup_failed, fetch_diagnostic } = adaptFetchByIdResult(fetched[i]);
  const identity_keys = backfillIdentityKeys("companies", existingRecord, row.identity_keys);
  return { json: { ...row, existingRecord, lookup_failed, fetch_diagnostic, identity_keys } };
});

// zoominfoToken.js — pure token cache/refresh helpers for the ZoomInfo OAuth2 flow.
//
// ZoomInfo (Okta) issues short-lived bearer tokens. For AUTONOMOUS operation the
// workflow must mint its own token from long-lived client_id + client_secret and
// re-mint when it expires or is rejected (401) — never store a static token.
//
// These are PURE functions (no n8n, no network) so they unit-test against Node.
// In the local replica the Code node wraps them around $getWorkflowStaticData (cross-run
// cache), this.helpers.httpRequest, and Date.now(). In the n8n Cloud deploy (Phase 16
// split-code-node) the mint is done by a credential-bound "ZoomInfo Mint" HTTP node —
// these helpers run in the SECRET-FREE Token Gate/Cache Code nodes (cache + expiry +
// re-mint-on-401 decisioning only; no client_id/client_secret ever in a Code node).
//
// Cache shape stored in workflow static data: { access_token, exp, token_type }
//   exp = absolute expiry in epoch MILLISECONDS.

// Mint a new token iff there is no cached token or it is within `skewMs` of expiry.
// Minting slightly early (default 60s skew) avoids using a token that dies mid-request.
function needsMint(cached, nowMs, skewMs = 60000) {
  if (!cached || !cached.access_token || !cached.exp) return true;
  return cached.exp - nowMs <= skewMs;
}

// Absolute expiry (epoch ms) from the token response's `expires_in` (seconds).
// Missing/invalid expires_in -> conservative 5-minute lifetime so we re-mint soon
// rather than trust an unknown-lifetime token indefinitely.
function computeExpiry(expiresInSec, nowMs) {
  const secs = Number(expiresInSec);
  if (!Number.isFinite(secs) || secs <= 0) return nowMs + 5 * 60000;
  return nowMs + secs * 1000;
}

// Parse an OAuth token-endpoint response into the cache shape. Accepts the JSON
// object or a raw JSON string. Throws if no token field is present (fail loud —
// a tokenless response must not be cached as if valid).
function parseTokenResponse(body, nowMs) {
  const b = typeof body === "string" ? JSON.parse(body) : (body || {});
  const token = b.access_token || b.jwt || b.token;
  if (!token) throw new Error("ZoomInfo token response missing access_token");
  return {
    access_token: token,
    exp: computeExpiry(b.expires_in, nowMs),
    token_type: b.token_type || "Bearer",
  };
}

// A 401 means the token was rejected (expired/revoked) -> clear cache, re-mint, retry once.
// Other statuses (400/403/404/429/5xx) are NOT auth failures and must not trigger a re-mint.
function isAuthError(statusCode) {
  return Number(statusCode) === 401;
}

// Bug B (live 2026-07-28): n8n's this.helpers.httpRequest throws an AxiosError, whose
// status lives at `e.response.status` — a shape the original inline check
// (statusCode/httpCode/response.statusCode) never covered, so a real 401 was silently
// missed and the cache never cleared. Tries every shape actually observed in this
// runtime (axios; n8n's NodeApiError, whose httpCode is sometimes a STRING; a bare
// statusCode) and, as a last resort, parses the "status code NNN" trailer n8n/axios
// append to the error message. Returns NaN (never a false 401) when nothing usable is
// found — isAuthError(NaN) is false, matching the safe conservative default.
function extractErrorStatus(e) {
  if (!e) return NaN;
  const candidates = [
    e.statusCode,
    e.httpCode,
    e.response && e.response.status,
    e.response && e.response.statusCode,
  ];
  for (const c of candidates) {
    if (c !== undefined && c !== null && c !== "") {
      const n = Number(c);
      if (Number.isFinite(n)) return n;
    }
  }
  const m = /status code (\d{3})/i.exec((e && e.message) || "");
  return m ? Number(m[1]) : NaN;
}

// --- n8n wrapper: ZoomInfo token cache gate (CLOUD split-code-node, secret-free) ---
// Never reads client_id/client_secret — only the credential-bound "ZoomInfo Mint" HTTP
// node touches those (Task 2 decision).
const sd = $getWorkflowStaticData("global");
const gateRows = (function () { try { return $('Company Gate').all(); } catch (e) { return []; } })();
const items = $input.all();
return items.map((item, i) => {
  const row = (gateRows[i] && gateRows[i].json) || item.json || {};
  const cached = sd.zoominfo;
  const needs_mint = needsMint(cached, Date.now());
  return { json: { ...row, zoom_needs_mint: needs_mint,
                   zoom_token: needs_mint ? null : cached.access_token } };
});

